def _encode(vals, left, right, root):
    if root == -1:
        return []
    out = []
    q = [root]
    for x in q:
        if x == -1:
            out.append(-1)
        else:
            out.append(vals[x])
            q.append(left[x])
            q.append(right[x])
    while out and out[-1] == -1:
        out.pop()
    return out


def recoverTree(s):
    vals, left, right = [], [], []
    path = []
    i, n = 0, len(s)
    while i < n:
        depth = 0
        while s[i] == '-':
            depth += 1
            i += 1
        v = 0
        while i < n and s[i] != '-':
            v = v * 10 + ord(s[i]) - 48
            i += 1
        k = len(vals)
        vals.append(v)
        left.append(-1)
        right.append(-1)
        del path[depth:]
        if path:
            p = path[-1]
            if left[p] == -1:
                left[p] = k
            else:
                right[p] = k
        path.append(k)
    return _encode(vals, left, right, 0)
